package com.afterglow.player;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;import org.json.*;
/** Cancellable foreground upload/poll/download client. AI runs on the configured server. */
public class StemService extends Service {
 public static volatile String status="Connect your computer's stem server to begin.";public static volatile boolean busy;static volatile String diagnostic="";
 volatile boolean cancelled;volatile java.lang.Process process;volatile HttpURLConnection connection;ExecutorService worker;PowerManager.WakeLock wake;String server,token,job;
 public static File output(Context c){return new File(c.getFilesDir(),"stems.zip");}
 public IBinder onBind(Intent i){return null;}public void onCreate(){super.onCreate();worker=Executors.newSingleThreadExecutor();getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("stems","Stem preparation",NotificationManager.IMPORTANCE_LOW));}
 Notification notice(){return new Notification.Builder(this,"stems").setSmallIcon(R.drawable.icon).setContentTitle("Afterglow · server stems").setContentText(status).setOngoing(busy).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).addAction(android.R.drawable.ic_menu_close_clear_cancel,"Cancel",PendingIntent.getService(this,32,new Intent(this,StemService.class).setAction("cancel"),PendingIntent.FLAG_IMMUTABLE)).build();}
 void progress(String value){status=value;getSystemService(NotificationManager.class).notify(3,notice());}void check()throws IOException{if(cancelled||Thread.currentThread().isInterrupted())throw new IOException("Stem preparation cancelled");}
 public int onStartCommand(Intent i,int flags,int id){if(i==null){stopSelf();return START_NOT_STICKY;}if("cancel".equals(i.getAction())){cancelled=true;if(process!=null)process.destroy();if(connection!=null)connection.disconnect();if(!busy)stopSelf();return START_NOT_STICKY;}if(busy)return START_NOT_STICKY;busy=true;cancelled=false;startForeground(3,notice());wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Afterglow:stems");wake.acquire(65*60*1000L);worker.execute(()->{try{server=ServerSettings.url(this);token=ServerSettings.token(this);if(token.isEmpty())throw new IOException("Add the server token in Studio's server settings");JSONObject health=json("GET","/health",null);if(!"afterglow-stems".equals(health.optString("service")))throw new IOException("This is not an Afterglow stem server");if("test".equals(i.getAction()))progress("Connected · four-stem Demucs server ready");else{separate(i.getStringExtra("uri"),i.getStringExtra("title"));progress("Four stems ready · export vocals, drums, bass and other");}}catch(Exception e){progress(cancelled?"Stem preparation cancelled":e instanceof ConnectException?"Cannot reach server. Start it on your computer and reconnect USB.":e.getMessage()==null?"Server stem preparation failed":e.getMessage());}finally{if(job!=null){try{HttpURLConnection c=open("DELETE","/jobs/"+job);c.getResponseCode();c.disconnect();}catch(Exception ignored){}job=null;}busy=false;if(wake.isHeld())wake.release();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}});return START_NOT_STICKY;}
 HttpURLConnection open(String method,String path)throws IOException{HttpURLConnection c=(HttpURLConnection)new URL(server+path).openConnection();c.setRequestMethod(method);c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(60000);c.setRequestProperty("Authorization","Bearer "+token);return c;}
 JSONObject json(String method,String path,File upload)throws Exception{check();HttpURLConnection c=open(method,path);connection=c;try{if(upload!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","audio/wav");c.setFixedLengthStreamingMode(upload.length());try(InputStream in=new FileInputStream(upload);OutputStream out=c.getOutputStream()){byte[] b=new byte[65536];long total=0,notified=0;int n;while((n=in.read(b))!=-1){check();out.write(b,0,n);total+=n;if(total-notified>1048576){progress("Uploading audio to your computer · "+(total*100/upload.length())+"%");notified=total;}}}}int code=c.getResponseCode();InputStream input=code>=200&&code<300?c.getInputStream():c.getErrorStream();if(input==null)throw new IOException("Stem server returned "+code);ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=input){copy(in,out,1048576);}JSONObject json=new JSONObject(out.toString("UTF-8"));if(code<200||code>=300)throw new IOException(json.optString("error","Stem server returned "+code));return json;}finally{c.disconnect();connection=null;}}
 void run(List<String> args,File base)throws Exception{check();ProcessBuilder pb=new ProcessBuilder(args).redirectErrorStream(true);String nativePath=getApplicationInfo().nativeLibraryDir;pb.environment().put("LD_LIBRARY_PATH",nativePath+":"+new File(base,"ffmpeg/usr/lib").getAbsolutePath()+":"+new File(base,"python/usr/lib").getAbsolutePath());process=pb.start();java.lang.Process p=process;ScheduledExecutorService timer=Executors.newSingleThreadScheduledExecutor();ScheduledFuture<?> timeout=timer.schedule(()->p.destroy(),10,TimeUnit.MINUTES);try(BufferedReader in=new BufferedReader(new InputStreamReader(p.getInputStream()))){String line;StringBuilder tail=new StringBuilder();while((line=in.readLine())!=null){check();tail.append(line).append('\n');if(tail.length()>5000)tail.delete(0,tail.length()-5000);}diagnostic=tail.toString();int exit=p.waitFor();check();if(exit!=0)throw new IOException("Audio conversion failed. Try another track.");}finally{timeout.cancel(false);timer.shutdownNow();if(p.isAlive())p.destroy();process=null;}}
 void copy(InputStream in,OutputStream out,long cap)throws Exception{byte[] b=new byte[65536];int n;long total=0;while((n=in.read(b))!=-1){check();total+=n;if(total>cap)throw new IOException("Audio exceeds the processing size limit");out.write(b,0,n);}}
 void separate(String uri,String title)throws Exception{
  if(uri==null||uri.isEmpty())throw new IOException("Choose a track first");if(getFilesDir().getUsableSpace()<1024L*1024*1024)throw new IOException("Free at least 1 GB before preparing stems");
  File dir=new File(getCacheDir(),"stem-work");dir.mkdirs();File source=new File(dir,"source"),wav=new File(dir,"input.wav"),zip=new File(getFilesDir(),"stems.zip.part");
  try{progress("Preparing audio for your server…");File cached=AudioCache.find(this,uri);try(InputStream in="demo".equals(uri)?getAssets().open("demo.wav"):cached!=null?new FileInputStream(cached):getContentResolver().openInputStream(Uri.parse(uri));OutputStream out=new FileOutputStream(source)){if(in==null)throw new IOException("Cannot read selected audio");copy(in,out,200L*1024*1024);}
   android.media.MediaMetadataRetriever meta=new android.media.MediaMetadataRetriever();try{meta.setDataSource(source.getAbsolutePath());long duration=Long.parseLong(meta.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION));if(duration<=0||duration>600000)throw new IOException("Stem preparation supports tracks up to 10 minutes");}finally{meta.release();}
   AudioDownloader engine=new AudioDownloader(this);File base=engine.initialize(message->progress(message));String nativePath=getApplicationInfo().nativeLibraryDir;
   run(Arrays.asList(nativePath+"/libffmpeg.so","-nostdin","-y","-i",source.getAbsolutePath(),"-vn","-acodec","pcm_s16le","-ar","44100","-ac","2",wav.getAbsolutePath()),base);progress("Uploading audio to your computer…");job=java.util.UUID.randomUUID().toString().replace("-","");json("POST","/jobs/"+job,wav);if(!job.matches("[a-f0-9]{32}"))throw new IOException("Invalid server job ID");long started=SystemClock.elapsedRealtime();
   while(true){check();JSONObject state=json("GET","/jobs/"+job,null);String phase=state.getString("state");if("complete".equals(phase))break;if("failed".equals(phase)||"cancelled".equals(phase))throw new IOException(state.optString("message","Server job stopped"));progress(state.optString("message","Separating on server…"));if(SystemClock.elapsedRealtime()-started>60*60*1000L)throw new IOException("Server job exceeded one hour");Thread.sleep(2000);}
   progress("Downloading four stems…");HttpURLConnection c=open("GET","/jobs/"+job+"/result");connection=c;try{if(c.getResponseCode()!=200)throw new IOException("Could not download stems");try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(zip)){copy(in,out,500L*1024*1024);}}finally{c.disconnect();connection=null;}
   try(ZipFile check=new ZipFile(zip)){for(String name:new String[]{"vocals.wav","drums.wav","bass.wav","other.wav"}){ZipEntry entry=check.getEntry(name);if(entry==null||entry.getSize()<44)throw new IOException("Server returned incomplete stems");}}check();if(!zip.renameTo(output(this)))throw new IOException("Could not save stem export");
  }finally{for(File f:new File[]{source,wav,zip})f.delete();dir.delete();}
 }
 public void onTimeout(int id,int type){cancelled=true;if(process!=null)process.destroy();if(connection!=null)connection.disconnect();stopSelf();}public void onDestroy(){cancelled=true;if(process!=null)process.destroy();if(connection!=null)connection.disconnect();worker.shutdownNow();if(wake!=null&&wake.isHeld())wake.release();busy=false;super.onDestroy();}
}
